import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.CYjxsSA2.js";const u=JSON.parse('{"title":"云上综合","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cloud.md","filePath":"guide/cloud.md"}'),d={name:"guide/cloud.md"};function l(n,t,i,s,h,g){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="云上综合" tabindex="-1">云上综合 <a class="header-anchor" href="#云上综合" aria-label="Permalink to &quot;云上综合&quot;">​</a></h1><p><strong>云上综合</strong>处理的是<strong>公有云开放平台</strong>：拿到一组 AK/SK 之后，枚举与利用云上资产。</p><h2 id="版面" tabindex="-1">版面 <a class="header-anchor" href="#版面" aria-label="Permalink to &quot;版面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>内容</th></tr></thead><tbody><tr><td><strong>云资产栏</strong></td><td>已发现的云资产</td></tr><tr><td><strong>凭据栏</strong></td><td>填 AK / SK（可选 STS Token），密钥字段为密码框</td></tr><tr><td><strong>能力清单</strong></td><td>按四组组织：云存储工具 / 云服务工具 / 其他工具 / API 接口库</td></tr><tr><td><strong>执行结果</strong></td><td>每一步的端点、方法、路径、请求体与响应原文</td></tr></tbody></table><h2 id="覆盖范围" tabindex="-1">覆盖范围 <a class="header-anchor" href="#覆盖范围" aria-label="Permalink to &quot;覆盖范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>族</th><th>覆盖</th></tr></thead><tbody><tr><td><strong>对象存储</strong></td><td>七牛 / 腾讯 COS / 青云 / 阿里 OSS / 又拍 / AWS S3（含兼容实现）/ 京东 / 金山 / MinIO</td></tr><tr><td><strong>云平台</strong></td><td>阿里云 / 腾讯云 / 华为云 / UCloud / AWS</td></tr></tbody></table><h2 id="结果怎么看" tabindex="-1">结果怎么看 <a class="header-anchor" href="#结果怎么看" aria-label="Permalink to &quot;结果怎么看&quot;">​</a></h2><ul><li><strong>能证明的才写结论</strong>：成功只认「返回成功且响应内无错误」，否则把对端原文摆出来由你判断</li><li><strong>不认识的接口不去猜</strong>：每一族都留了「自定义调用」入口，Action 与参数自己填</li><li><strong>不确定的前提写在说明里</strong>：需要开白名单、需要先开通服务的接口会标注出来</li><li><strong>一次性链接只展示不重放</strong>：例如控制台免登录链接，看一眼即失效</li></ul><h2 id="网络出口" tabindex="-1">网络出口 <a class="header-anchor" href="#网络出口" aria-label="Permalink to &quot;网络出口&quot;">​</a></h2><p>云上综合的出站可以单独指定代理，在<strong>系统配置 → 全局代理 → 代理路由</strong>里为「云上综合」选择出口。适合「扫描走直连、云上走代理」这类组合。</p><h2 id="典型流程" tabindex="-1">典型流程 <a class="header-anchor" href="#典型流程" aria-label="Permalink to &quot;典型流程&quot;">​</a></h2><ol><li>从代码仓库、前端 JS 或<a href="/vaelor/guide/webcrawl.html">漏洞测绘</a>的敏感信息里拿到一组 AK/SK</li><li>进入云上综合，选择对应的云平台或存储族，填入凭据</li><li>先跑「列举」类能力确认凭据有效，再按清单逐条深入</li><li>高价值结果留痕，回到<a href="/vaelor/guide/vulnreports.html">漏洞管理</a>分诊</li></ol>',12)])])}const b=a(d,[["render",l]]);export{u as __pageData,b as default};
